// MySpace\MyS_Front\src\paginas\logeo\Registro.jsx

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Registro.css";
import { registro } from "../../Api";
import { validarEmail, validarNombreCompleto } from "../../Api/validaciones"; 
import Base_Main from "../../bases/Base_Main"; 

export default function Registro() {
  
  const navigate = useNavigate();

  const [nombre, setNombre] = useState("");
  const [apPaterno, setApPaterno] = useState("");
  const [apMaterno, setApMaterno] = useState("");
  const [correo, setCorreo] = useState("");
  const [pass1, setPass1] = useState("");
  const [pass2, setPass2] = useState("");
  const [fechaNacimiento, setFechaNacimiento] = useState("");
  const [loading, setLoading] = useState(false);

  // Estados para manejar errores y estado de validación AJAX
  const [emailError, setEmailError] = useState('');
  const [nombreCompletoError, setNombreCompletoError] = useState('');
  const [isEmailValidating, setIsEmailValidating] = useState(false);
  const [isNameValidating, setIsNameValidating] = useState(false);
  const [registroError, setRegistroError] = useState(''); 

  // ----------------------------------------------------
  // FUNCIONES DE VALIDACIÓN AJAX (ON BLUR)
  // ----------------------------------------------------

  const handleBlurEmail = async () => {
    if (correo.length === 0 || isEmailValidating) {
        setEmailError('');
        return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(correo)) {
        setEmailError("Formato de correo inválido.");
        return;
    }

    setIsEmailValidating(true);
    setEmailError('Verificando disponibilidad...'); 

    try {
        const data = await validarEmail(correo);
        if (data.disponible === false) {
            setEmailError(data.mensaje); 
        } else {
            setEmailError('');
        }
    } catch (error) {
        setEmailError('Error de conexión al validar el correo.');
    } finally {
        setIsEmailValidating(false);
    }
  };

  const handleBlurNombreCompleto = async () => {
    if (nombre.length === 0 || apPaterno.length === 0 || apMaterno.length === 0 || isNameValidating) {
        setNombreCompletoError('');
        return;
    }

    setIsNameValidating(true);
    setNombreCompletoError('Verificando combinación de nombre...');

    try {
        const data = await validarNombreCompleto(nombre, apPaterno, apMaterno);
        if (data.disponible === false) {
            setNombreCompletoError(data.mensaje); 
        } else {
            setNombreCompletoError('');
        }
    } catch (error) {
        setNombreCompletoError('Error de conexión al validar el nombre.');
    } finally {
        setIsNameValidating(false);
    }
  };

  // ----------------------------------------------------
  // FUNCIÓN DE REGISTRO
  // ----------------------------------------------------
  const registrarUsuario = async (e) => {
    e.preventDefault();
    setRegistroError(''); 

    if (emailError || nombreCompletoError || isEmailValidating || isNameValidating) {
        alert("Por favor, corrige los errores de validación o espera a que terminen las verificaciones.");
        return;
    }

    if (pass1 !== pass2) {
      setRegistroError("Las contraseñas no coinciden");
      return;
    }
    
    if (pass1.length < 6) {
      setRegistroError("La contraseña debe tener al menos 6 caracteres");
      return;
    }
    
    if (!fechaNacimiento) {
      setRegistroError("Por favor ingresa tu fecha de nacimiento");
      return;
    }
    
    setLoading(true);
    
    try {
      const userData = {
        nombre: nombre,
        apellido_p: apPaterno,
        apellido_m: apMaterno,
        correo: correo,
        contrasena: pass1,
        fecha_nacimiento: new Date(fechaNacimiento).toISOString(),
      };
      
      const data = await registro(userData);
      
      const usuarioLogeado = {
        correo: data.usuario.correo,
        nombre: data.usuario.nombre,
        apellido_p: data.usuario.apellido_p,
        apellido_m: data.usuario.apellido_m,
        fecha_nacimiento: data.usuario.fecha_nacimiento,
        nom_usuario: data.perfil?.nom_usuario || data.usuario.nombre,
        descripcion: data.perfil?.descripcion || "",
        imagen: data.perfil?.foto_perfil || "https://via.placeholder.com/150"
      };
      
      localStorage.setItem("usuarioLogeado", JSON.stringify(usuarioLogeado));
      
      alert(`¡Bienvenido ${data.usuario.nombre}! Tu cuenta ha sido creada.`);
      navigate("/perfil");
      
    } catch (error) {
      console.error("Error en registro:", error);
      
      let errorMsg = "Error de red o conexión.";

      if (error.response) {
            const errorData = error.response.data;
            if (errorData.error) {
                errorMsg = errorData.error; 
            } else if (errorData.correo) {
                errorMsg = `Error en correo: ${errorData.correo[0]}`;
            } else {
                 errorMsg = "Verifica todos los campos.";
            }
      }
      setRegistroError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Base_Main tituloPagina="Registro">
      <div className="registro-contenido">
        <form className="registro-forma" onSubmit={registrarUsuario}>
          <table>
            <tbody>
              <tr>
                <td>Nombre</td>
                <td>
                  <input
                    type="text"
                    value={nombre}
                    onChange={(e) => setNombre(e.target.value)}
                    onBlur={handleBlurNombreCompleto} 
                    required
                    disabled={loading || isNameValidating}
                  />
                </td>
              </tr>
              <tr>
                <td>Apellido Paterno</td>
                <td>
                  <input
                    type="text"
                    value={apPaterno}
                    onChange={(e) => setApPaterno(e.target.value)}
                    onBlur={handleBlurNombreCompleto} 
                    required
                    disabled={loading || isNameValidating}
                  />
                </td>
              </tr>
              <tr>
                <td>Apellido Materno</td>
                <td>
                  <input
                    type="text"
                    value={apMaterno}
                    onChange={(e) => setApMaterno(e.target.value)}
                    onBlur={handleBlurNombreCompleto} 
                    required
                    disabled={loading || isNameValidating}
                  />
                </td>
              </tr>
              {/* Eliminar estilos en línea */}
              {nombreCompletoError && (
                  <tr>
                      <td colSpan="2" className="error-mensaje">
                          <span>{nombreCompletoError}</span>
                      </td>
                  </tr>
              )}
              <tr>
                <td>Correo</td>
                <td>
                  <input
                    type="email"
                    value={correo}
                    onChange={(e) => setCorreo(e.target.value)}
                    onBlur={handleBlurEmail} 
                    required
                    disabled={loading || isEmailValidating}
                  />
                </td>
              </tr>
              {/* Eliminar estilos en línea */}
              {emailError && (
                  <tr>
                      <td colSpan="2" className="error-mensaje">
                          <span>{emailError}</span>
                      </td>
                  </tr>
              )}
              <tr>
                <td>Fecha de Nacimiento</td>
                <td>
                  <input
                    type="date"
                    value={fechaNacimiento}
                    onChange={(e) => setFechaNacimiento(e.target.value)}
                    required
                    disabled={loading}
                    max={new Date().toISOString().split('T')[0]}
                  />
                </td>
              </tr>
              <tr>
                <td>Contraseña</td>
                <td>
                  <input
                    type="password"
                    value={pass1}
                    onChange={(e) => setPass1(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Repetir Contraseña</td>
                <td>
                  <input
                    type="password"
                    value={pass2}
                    onChange={(e) => setPass2(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
               {/* Eliminar estilos en línea */}
              {registroError && (
                  <tr>
                      <td colSpan="2" className="error-mensaje">
                          <span>{registroError}</span>
                      </td>
                  </tr>
              )}
            </tbody>
          </table>

          <button 
            type="submit" 
            className="registro-boton"
            disabled={loading || emailError || nombreCompletoError || isEmailValidating || isNameValidating} 
          >
            {loading ? "Registrando..." : "Registrarse"}
          </button>

          <p className="registro-login">¿Ya tienes cuenta?</p>
          <a href="/cuenta">Iniciar sesión</a>
        </form>
      </div>
    </Base_Main>
  );
}
